INSERT INTO pharos_uam.employee (employee_id, okta_account_id, source_system, first_name, middle_name, last_name, email, employment_status, hire_date, termination_date, employee_class, company_name, country, business_unit, city, employee_last_synced_at, manager_employee_id, manager_first_name, manager_middle_name, manager_last_name, department, job_code, job_title, job_family_group, job_family, supplier)
VALUES (:employee_id, :okta_account_id, :source_system, :first_name, :middle_name, :last_name, :email, :employment_status, :hire_date, :termination_date, :employee_class, :company_name, :country, :business_unit, :city, :employee_last_synced_at, :manager_employee_id, :manager_first_name, :manager_middle_name, :manager_last_name, :department, :job_code, :job_title, :job_family_group, :job_family, :supplier)
ON CONFLICT(employee_id) DO UPDATE SET okta_account_id=EXCLUDED.okta_account_id, source_system=EXCLUDED.source_system, first_name=EXCLUDED.first_name, middle_name=EXCLUDED.middle_name, last_name=EXCLUDED.last_name, email=EXCLUDED.email, employment_status=EXCLUDED.employment_status, hire_date=EXCLUDED.hire_date, termination_date=EXCLUDED.termination_date, employee_class=EXCLUDED.employee_class, company_name=EXCLUDED.company_name, country=EXCLUDED.country, business_unit=EXCLUDED.business_unit, city=EXCLUDED.city, employee_last_synced_at=EXCLUDED.employee_last_synced_at, manager_employee_id=EXCLUDED.manager_employee_id, manager_first_name=EXCLUDED.manager_first_name, manager_middle_name=EXCLUDED.manager_middle_name, manager_last_name=EXCLUDED.manager_last_name, department=EXCLUDED.department, job_code=EXCLUDED.job_code, job_title=EXCLUDED.job_title, job_family_group=EXCLUDED.job_family_group, job_family=EXCLUDED.job_family, supplier=EXCLUDED.supplier, updated_at=clock_timestamp()
WHERE employee.okta_account_id IS NULL OR employee.okta_account_id=EXCLUDED.okta_account_id
